
# Database Inspection
# This script inspects the SQLite database generated by the Data Commons importer.
# It connects to the datacommons.db database using Python's built-in sqlite3 library.
# It retrieves and displays all tables available in the database.
# It displays each table's columns and their data types.
# It retrieves sample records from the observations table.
# It helps us understand how Data Commons stores the imported inflation data.
# It is used for database exploration and debugging without modifying the data.


# INPUT FILE:
# - data/transformed_data/datacommons/datacommons.db

# OUTPUT FOLDERS:
# - None. This script does not create folders.

# OUTPUT FILES:
# - None. This script does not create files or modify the database.

# EXPECTED OUTPUT:
# - Displays database table names in the PyCharm console.
# - Displays column names and data types for each table.
# - Displays sample inflation observations from the database.
# - Helps developers inspect and understand the database structure.



import sqlite3
from pathlib import Path

db_path = Path(
    "data/transformed_data/datacommons/datacommons.db"
)

if not db_path.is_file():
    raise FileNotFoundError(f"Database not found: {db_path}")

with sqlite3.connect(db_path) as conn:
    tables = conn.execute("""
        SELECT name
        FROM sqlite_master
        WHERE type = 'table'
        ORDER BY name
    """).fetchall()

    for (table_name,) in tables:
        print(f"\nTABLE: {table_name}")

        columns = conn.execute(
            f"PRAGMA table_info('{table_name}')"
        ).fetchall()

        for column in columns:
            print(f"  {column[1]} ({column[2]})")

    print("\nSAMPLE OBSERVATIONS:")
    rows = conn.execute(
        "SELECT * FROM observations LIMIT 5"
    ).fetchall()

    for row in rows:
        print(row)
